// Dati di Frasi e Componi (sezione Pratica).
// Estratto da App.jsx per ridurre le dimensioni del file principale.

export function pg(pattern, pattern_it, phrases) {
  return { pattern, pattern_it, phrases: phrases.map(([ru, it]) => ({ ru, it })) };
}

export function cf(it, ru, tokens) {
  return { it, ru, tokens };
}

